   113  /*!
   114   * \brief   readHeaderSpix()
   115   *
   116   * \param[in]    filename
   117   * \param[out]   pwidth     width
   118   * \param[out]   pheight    height
   119   * \param[out]   pbps       bits/sample
   120   * \param[out]   pspp       samples/pixel
   121   * \param[out]   piscmap    [optional]  input NULL to ignore
   122   * \return  0 if OK, 1 on error
   123   *
   124   * <pre>
   125   * Notes:
   126   *      (1) If there is a colormap, iscmap is returned as 1; else 0.
   127   * </pre>
   128   */
   129  l_ok
   130  readHeaderSpix(const char *filename,
   131                 l_int32    *pwidth,
   132                 l_int32    *pheight,
   133                 l_int32    *pbps,
   134                 l_int32    *pspp,
   135                 l_int32    *piscmap)
   136  {
   137  l_int32  ret;
   138  FILE    *fp;
   139
   140      PROCNAME("readHeaderSpix");
   141
   142      if (!filename)
   143          return ERROR_INT("filename not defined", procName, 1);
   144      if (!pwidth || !pheight || !pbps || !pspp)
   145          return ERROR_INT("input ptr(s) not defined", procName, 1);
   146      if ((fp = fopenReadStream(filename)) == NULL)
   147          return ERROR_INT("image file not found", procName, 1);
   148      ret = freadHeaderSpix(fp, pwidth, pheight, pbps, pspp, piscmap);
   149      fclose(fp);
   150      return ret;
   151  }
