   154  /*!
   155   * \brief   freadHeaderSpix()
   156   *
   157   * \param[in]    fp        file stream
   158   * \param[out]   pwidth    width
   159   * \param[out]   pheight   height
   160   * \param[out]   pbps      bits/sample
   161   * \param[out]   pspp      samples/pixel
   162   * \param[out]   piscmap   [optional]  input NULL to ignore
   163   * \return  0 if OK, 1 on error
   164   *
   165   * <pre>
   166   * Notes:
   167   *      (1) If there is a colormap, iscmap is returned as 1; else 0.
   168   * </pre>
   169   */
   170  l_ok
   171  freadHeaderSpix(FILE     *fp,
   172                  l_int32  *pwidth,
   173                  l_int32  *pheight,
   174                  l_int32  *pbps,
   175                  l_int32  *pspp,
   176                  l_int32  *piscmap)
   177  {
   178  l_int32   nbytes, ret;
   179  l_uint32  data[6];
   180
   181      PROCNAME("freadHeaderSpix");
   182
   183      if (!fp)
   184          return ERROR_INT("stream not defined", procName, 1);
   185      if (!pwidth || !pheight || !pbps || !pspp)
   186          return ERROR_INT("input ptr(s) not defined", procName, 1);
   187
   188      nbytes = fnbytesInFile(fp);
   189      if (nbytes < 32)
   190          return ERROR_INT("file too small to be spix", procName, 1);
   191      if (fread(data, 4, 6, fp) != 6)
   192          return ERROR_INT("error reading data", procName, 1);
   193      ret = sreadHeaderSpix(data, pwidth, pheight, pbps, pspp, piscmap);
   194      return ret;
   195  }
