   198  /*!
   199   * \brief   sreadHeaderSpix()
   200   *
   201   * \param[in]    data
   202   * \param[out]   pwidth    width
   203   * \param[out]   pheight   height
   204   * \param[out]   pbps      bits/sample
   205   * \param[out]   pspp      samples/pixel
   206   * \param[out]   piscmap   [optional]  input NULL to ignore
   207   * \return  0 if OK, 1 on error
   208   *
   209   * <pre>
   210   * Notes:
   211   *      (1) If there is a colormap, iscmap is returned as 1; else 0.
   212   * </pre>
   213   */
   214  l_ok
   215  sreadHeaderSpix(const l_uint32  *data,
   216                  l_int32         *pwidth,
   217                  l_int32         *pheight,
   218                  l_int32         *pbps,
   219                  l_int32         *pspp,
   220                  l_int32         *piscmap)
   221  {
   222  char    *id;
   223  l_int32  d, ncolors;
   224
   225      PROCNAME("sreadHeaderSpix");
   226
   227      if (!data)
   228          return ERROR_INT("data not defined", procName, 1);
   229      if (!pwidth || !pheight || !pbps || !pspp)
   230          return ERROR_INT("input ptr(s) not defined", procName, 1);
   231      *pwidth = *pheight = *pbps = *pspp = 0;
   232      if (piscmap)
   233        *piscmap = 0;
   234
   235          /* Check file id */
   236      id = (char *)data;
   237      if (id[0] != 's' || id[1] != 'p' || id[2] != 'i' || id[3] != 'x')
   238          return ERROR_INT("not a valid spix file", procName, 1);
   239
   240      *pwidth = data[1];
   240      *pwidth = data[1];
   241      *pheight = data[2];
   242      d = data[3];
   243      if (d <= 16) {
   244        *pbps = d;
   245        *pspp = 1;
   246      } else {
   247        *pbps = 8;
   248        *pspp = d / 8;  /* if the pix is 32 bpp, call it 4 samples */
   249      }
   250      ncolors = data[5];
   251      if (piscmap)
   252          *piscmap = (ncolors == 0) ? 0 : 1;
   253
   254      return 0;
   255  }
