   258  /*-----------------------------------------------------------------------*
   259   *                            Writing spix to file                       *
   260   *-----------------------------------------------------------------------*/
   261  /*!
   262   * \brief   pixWriteStreamSpix()
   263   *
   264   * \param[in]    fp     file stream
   265   * \param[in]    pix
   266   * \return  0 if OK; 1 on error
   267   */
   268  l_ok
   269  pixWriteStreamSpix(FILE  *fp,
   270                     PIX   *pix)
   271  {
   272  l_uint8  *data;
   273  size_t    size;
   274
   275      PROCNAME("pixWriteStreamSpix");
   276
   277      if (!fp)
   278          return ERROR_INT("stream not defined", procName, 1);
   279      if (!pix)
   280          return ERROR_INT("pix not defined", procName, 1);
   281
   282      if (pixWriteMemSpix(&data, &size, pix))
   283          return ERROR_INT("failure to write pix to memory", procName, 1);
   284      fwrite(data, 1, size, fp);
   285      LEPT_FREE(data);
   286      return 0;
   287  }
