   290  /*-----------------------------------------------------------------------*
   291   *       Low-level serialization of pix to/from memory (uncompressed)    *
   292   *-----------------------------------------------------------------------*/
   293  /*!
   294   * \brief   pixReadMemSpix()
   295   *
   296   * \param[in]    data    const; uncompressed
   297   * \param[in]    size    bytes of data
   298   * \return  pix, or NULL on error
   299   */
   300  PIX *
   301  pixReadMemSpix(const l_uint8  *data,
   302                 size_t          size)
   303  {
   304      return pixDeserializeFromMemory((l_uint32 *)data, size);
   305  }
