   308  /*!
   309   * \brief   pixWriteMemSpix()
   310   *
   311   * \param[out]   pdata    data of serialized, uncompressed pix
   312   * \param[out]   psize    size of returned data
   313   * \param[in]    pix      all depths; colormap OK
   314   * \return  0 if OK, 1 on error
   315   */
   316  l_ok
   317  pixWriteMemSpix(l_uint8  **pdata,
   318                  size_t    *psize,
   319                  PIX       *pix)
   320  {
   321      return pixSerializeToMemory(pix, (l_uint32 **)pdata, psize);
   322  }
